package com.digitalbase.ticketing.model;import com.digitalbase.ticketing.enums.ProductStatus; // ---> Enum ကို Import လုပ်ပါ <---import jakarta.persistence.*;import lombok.*;import java.time.Instant;@Entity@Table(name = "client_products")@Data@Builder@NoArgsConstructor@AllArgsConstructorpublic class ClientProduct {    @Id    @GeneratedValue(strategy = GenerationType.IDENTITY)    private Long id;    @ManyToOne(fetch = FetchType.LAZY)    @JoinColumn(name = "user_id", nullable = false)    private User user;    @ManyToOne(fetch = FetchType.LAZY)    @JoinColumn(name = "product_id", nullable = false)    private Product product;    @Column(name = "support_plan")    private String supportPlan;    @Column(name = "purchased_date", nullable = false)    private Instant purchasedDate;    @Column(name = "plan_start_date")    private Instant planStartDate;    @Column(name = "plan_end_date", nullable = false)    private Instant planEndDate;    @Column(name = "available_minutes")    private Integer availableMinutes;    @Column(name = "total_minutes")    private Integer totalMinutes;    @Column(name = "last_alert_date")    private Instant lastAlertDate;    // ❌ ဤနေရာတွင် ရှိခဲ့သော @Column(name = "is_active") ကို ဖျက်လိုက်ပါပြီ    // ✅ အသစ်ပြင်ဆင်ထားသော Enum Status (Database တွင် စာသားအတိုင်း ACTIVE ဟု သိမ်းဆည်းမည်)    @Enumerated(EnumType.STRING)    @Column(name = "status", nullable = false)    private ProductStatus status;}